"""Discount rules.

# clevin-b: MAUVE-42

``percentage_off``/``flat_off`` operate on ``Decimal`` amounts (used by
``invoice.line_amount``). ``bulk_rule`` keeps returning a plain float
percentage — it is not a money amount and ``tests/test_smoke.py`` pins its
float return type unchanged.
"""

from __future__ import annotations

from decimal import Decimal

from .money import quantize


def percentage_off(amount: Decimal, percent: Decimal) -> Decimal:
    return quantize(amount * (Decimal("1") - percent / Decimal("100")))


def flat_off(amount: Decimal, discount: Decimal) -> Decimal:
    return quantize(max(amount - discount, Decimal("0")))


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

"""Invoice rendering. Shares tax rules with cart.py via money.TAX_RATE.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import Money, TAX_RATE, quantize, zero

__all__ = ["TAX_RATE", "InvoiceLine", "Invoice"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def _line_amount_decimal(self, line: InvoiceLine) -> Decimal:
        gross = catalog.lookup(line.sku).unit_price * line.quantity
        return discounts.percentage_off(gross, line.discount_percent)

    def line_amount(self, line: InvoiceLine) -> Money:
        return Money(self._line_amount_decimal(line))

    def subtotal(self) -> Money:
        total = Decimal("0")
        for line in self.lines:
            total += self._line_amount_decimal(line)
        return Money(quantize(total))

    def tax(self) -> Money:
        taxable = Decimal("0")
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable += self._line_amount_decimal(line)
        return Money(quantize(taxable * TAX_RATE))

    def total(self) -> Money:
        return self.subtotal() + self.tax()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(
                f"{product.name} x{line.quantity}  {self.line_amount(line).amount:.2f}"
            )
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Aggregate reporting over invoices.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from collections import defaultdict

from .invoice import Invoice
from .money import Money, zero


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Money] = defaultdict(zero)
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] = totals[line.sku] + invoice.line_amount(line)
    return dict(totals)


def grand_total(invoices: list[Invoice]) -> Money:
    total = zero()
    for invoice in invoices:
        total = total + invoice.total()
    return total

